import{j as i,b as l,c as e,ae as n}from"./chunks/framework.DkjvVb1g.js";const g=JSON.parse('{"title":"Agent 开发调优面试题","description":"Agent 后端调优方法，覆盖 Prompt、工具调用、上下文、成本、延迟、稳定性和评测。","frontmatter":{"title":"Agent 开发调优面试题","description":"Agent 后端调优方法，覆盖 Prompt、工具调用、上下文、成本、延迟、稳定性和评测。","date":"2026-06-11T00:00:00.000Z","tags":["Agent","调优","评测"],"categories":["面经"]},"headers":[],"relativePath":"interview/agent-backend/agent-optimization.md","filePath":"interview/agent-backend/agent-optimization.md","lastUpdated":1782271370000}'),t={name:"interview/agent-backend/agent-optimization.md"};function s(p,a,r,o,d,h){return l(),e("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1781136000000"},[...a[0]||(a[0]=[n(`<h1 id="agent-开发调优面试题" tabindex="-1">Agent 开发调优面试题 <a class="header-anchor" href="#agent-开发调优面试题" aria-label="Permalink to “Agent 开发调优面试题”">​</a></h1><h2 id="_1-agent-效果不好如何排查" tabindex="-1">1. Agent 效果不好如何排查？ <a class="header-anchor" href="#_1-agent-效果不好如何排查" aria-label="Permalink to “1. Agent 效果不好如何排查？”">​</a></h2><p>按链路拆解：</p><ol><li>用户意图是否识别正确？</li><li>Prompt 是否明确角色、目标、约束和输出格式？</li><li>工具 schema 是否清晰？</li><li>工具结果是否过长或噪声太多？</li><li>上下文是否缺失或被无关信息干扰？</li><li>模型是否适合该任务？</li><li>是否有评测集和失败样本归因？</li></ol><h2 id="_2-prompt-如何调优" tabindex="-1">2. Prompt 如何调优？ <a class="header-anchor" href="#_2-prompt-如何调优" aria-label="Permalink to “2. Prompt 如何调优？”">​</a></h2><p>通用原则：</p><ul><li>明确目标：告诉模型要完成什么。</li><li>明确边界：告诉模型不能做什么。</li><li>明确格式：使用 JSON schema 或示例约束输出。</li><li>明确决策规则：什么时候调用工具，什么时候直接回答。</li><li>提供 few-shot：覆盖典型和边界样例。</li><li>控制上下文：减少无关内容。</li></ul><p>常见结构：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>角色定义</span></span>
<span class="line"><span>任务目标</span></span>
<span class="line"><span>可用工具</span></span>
<span class="line"><span>调用规则</span></span>
<span class="line"><span>输出格式</span></span>
<span class="line"><span>错误处理策略</span></span>
<span class="line"><span>示例</span></span>
<span class="line"><span>用户输入</span></span></code></pre></div><h2 id="_3-如何避免-agent-无限循环" tabindex="-1">3. 如何避免 Agent 无限循环？ <a class="header-anchor" href="#_3-如何避免-agent-无限循环" aria-label="Permalink to “3. 如何避免 Agent 无限循环？”">​</a></h2><p>措施：</p><ul><li>设置最大步数和最大工具调用次数。</li><li>对相同工具+相同参数做重复调用检测。</li><li>维护任务状态，要求每一步必须产生状态变化。</li><li>工具失败达到阈值后走 fallback。</li><li>让模型在每轮判断是否已经满足完成条件。</li></ul><h2 id="_4-如何降低-agent-延迟" tabindex="-1">4. 如何降低 Agent 延迟？ <a class="header-anchor" href="#_4-如何降低-agent-延迟" aria-label="Permalink to “4. 如何降低 Agent 延迟？”">​</a></h2><p>优化点：</p><ul><li>减少 LLM 调用轮数。</li><li>小模型做意图识别，大模型做复杂推理。</li><li>RAG 检索、工具调用并行化。</li><li>缓存稳定结果，如系统 prompt、检索结果、工具结果。</li><li>使用流式输出改善体感。</li><li>控制上下文长度，压缩工具返回。</li></ul><h2 id="_5-如何降低成本" tabindex="-1">5. 如何降低成本？ <a class="header-anchor" href="#_5-如何降低成本" aria-label="Permalink to “5. 如何降低成本？”">​</a></h2><p>措施：</p><ul><li>Prompt 压缩，减少历史上下文。</li><li>模型路由：简单任务走便宜模型。</li><li>Embedding 和检索结果缓存。</li><li>工具结果摘要化。</li><li>批处理离线任务。</li><li>对高频问题使用 FAQ 或模板直出。</li></ul><h2 id="_6-如何提升工具调用准确率" tabindex="-1">6. 如何提升工具调用准确率？ <a class="header-anchor" href="#_6-如何提升工具调用准确率" aria-label="Permalink to “6. 如何提升工具调用准确率？”">​</a></h2><p>关键点：</p><ul><li>工具名称语义明确。</li><li>参数 schema 尽量使用枚举、范围和描述。</li><li>工具数量不要过多，必要时先做工具路由。</li><li>给出正反例，说明什么时候不能调用。</li><li>后端对参数做强校验，失败时返回可修复错误。</li></ul><h2 id="_7-agent-评测怎么做" tabindex="-1">7. Agent 评测怎么做？ <a class="header-anchor" href="#_7-agent-评测怎么做" aria-label="Permalink to “7. Agent 评测怎么做？”">​</a></h2><p>评测维度：</p><ul><li>任务成功率</li><li>工具调用准确率</li><li>参数正确率</li><li>幻觉率</li><li>平均步骤数</li><li>平均耗时</li><li>token 成本</li><li>安全违规率</li></ul><p>评测方法：</p><ul><li>Golden Set：人工标注标准答案和期望工具调用。</li><li>Trace Replay：回放真实线上请求。</li><li>LLM-as-Judge：适合开放问答，但要做抽样人工校验。</li><li>A/B Test：比较不同 prompt、模型和检索策略。</li></ul><h2 id="_8-线上-agent-如何观测" tabindex="-1">8. 线上 Agent 如何观测？ <a class="header-anchor" href="#_8-线上-agent-如何观测" aria-label="Permalink to “8. 线上 Agent 如何观测？”">​</a></h2><p>必须记录：</p><ul><li>request id / session id / user id</li><li>prompt 版本和模型版本</li><li>每轮输入输出 token</li><li>tool call 参数、耗时、状态码</li><li>RAG 检索 query、召回文档、score</li><li>最终答案、用户反馈、错误栈</li></ul><p>注意脱敏，敏感字段不要明文落日志。</p>`,30)])])}const m=i(t,[["render",s]]);export{g as __pageData,m as default};
